#!/usr/bin/env python3
import os, sys, pathlib, re, json, stat, pwd, grp, time, datetime, hashlib, mimetypes, shlex, fnmatch
from help_data import LONG_COLORED, LONG_NOCOLOR, SHORT_COLORED, SHORT_NOCOLOR

def is_help(arg):
    return arg.lower() in ('--help','-h','/?','/h')
def is_nocolor(arg):
    return arg.lower() in ('--nocolor','--no-color','/nocolor','/no-color')
def is_no_errors(arg):
    return arg.lower() == '--no-errors'
def is_interactive(arg):
    return arg.lower() in ('--interactive','-i','/i')
def is_config(arg):
    low = arg.lower()
    if '=' in arg:
        prefix = arg.split('=',1)[0].lower()
        return prefix in ('--config','-c','/config','/c')
    return low in ('--config','-c','/config','/c')
def should_use_color(nocolor_flag):
    if nocolor_flag:
        return False
    if os.environ.get('NO_COLOR') is not None:
        return False
    return True
def print_help_long(use_color):
    txt = LONG_COLORED if use_color else LONG_NOCOLOR
    sys.stdout.write(txt)
def print_help_short(use_color):
    txt = SHORT_COLORED if use_color else SHORT_NOCOLOR
    sys.stdout.write(txt)
def error_config_requires_path():
    sys.stderr.write("Error: --config requires a path argument\n")
    sys.exit(2)
def handle_config_file(path):
    p = pathlib.Path(path)
    if not p.is_file():
        return "Could not open config file. Using default settings.\n"
    try:
        text = p.read_text()
        stripped = text.strip()
        if not stripped:
            return None
        if '=' not in stripped and not stripped.startswith('['):
            first_line = text.splitlines()[0] if text.splitlines() else ""
            col = len(first_line.strip()) + 1 if first_line.strip() else 5
            return f"TOML parse error at line 1, column {col}\n  |\n1 | {first_line}\n  |     ^\nkey with no value, expected `=`\n\n"
        return None
    except:
        return "Could not open config file. Using default settings.\n"

# Query engine will be imported
from query_engine import execute_query

def run_interactive(nocolor, no_errors, config_warning):
    use_color = should_use_color(nocolor)
    if config_warning:
        sys.stderr.write(config_warning)
    current_dir = os.getcwd()
    show_errors = not no_errors
    exited = False
    # Read stdin fully
    data = sys.stdin.read()
    # Split lines preserving? We need to handle each line
    lines = data.splitlines()
    # If stdin is empty, we still need to output CTRL-D at end
    # Process each line
    for raw in lines:
        stripped = raw.strip()
        if stripped == "":
            continue
        low = stripped.lower()
        if low == 'help':
            txt = LONG_COLORED if use_color else LONG_NOCOLOR
            sys.stdout.write(txt)
        elif low == 'pwd':
            sys.stdout.write(current_dir + "\n")
        elif low.startswith('cd '):
            # case-insensitive cd
            # find first space
            parts = stripped.split(None,1)
            target = parts[1].strip() if len(parts)>1 else ""
            if target == "":
                continue
            if os.path.isabs(target):
                new_path = os.path.normpath(target)
            else:
                new_path = os.path.normpath(os.path.join(current_dir, target))
            try:
                if not os.path.isdir(new_path):
                    raise FileNotFoundError(2, "No such file or directory")
                current_dir = os.path.abspath(new_path)
            except:
                msg = "cd: No such file or directory (os error 2)\n"
                if use_color:
                    msg = "\x1b[33mcd\x1b[0m: No such file or directory (os error 2)\n"
                if show_errors:
                    sys.stderr.write(msg)
        elif low.startswith('errors'):
            parts = stripped.split()
            if len(parts) == 1:
                state = "ON" if show_errors else "OFF"
                if use_color:
                    sys.stdout.write(f"Errors are \x1b[33m{state}\x1b[0m\n")
                else:
                    sys.stdout.write(f"Errors are {state}\n")
            else:
                arg2 = parts[1].lower()
                if arg2 == 'on':
                    show_errors = True
                    if use_color:
                        sys.stdout.write("Errors are \x1b[33mON\x1b[0m\n")
                    else:
                        sys.stdout.write("Errors are ON\n")
                elif arg2 == 'off':
                    show_errors = False
                    if use_color:
                        sys.stdout.write("Errors are \x1b[33mOFF\x1b[0m\n")
                    else:
                        sys.stdout.write("Errors are OFF\n")
                else:
                    state = "ON" if show_errors else "OFF"
                    if use_color:
                        sys.stdout.write(f"Errors are \x1b[33m{state}\x1b[0m\n")
                    else:
                        sys.stdout.write(f"Errors are {state}\n")
        elif low in ('exit','quit'):
            exited = True
            break
        else:
            out, err, code = execute_query(stripped, cwd=current_dir, use_color=use_color)
            # For interactive, errors respect show_errors toggle
            if out:
                sys.stdout.write(out)
                if not out.endswith('\n'):
                    sys.stdout.write('\n')
            if err and show_errors:
                sys.stderr.write(err)
            # code handling? interactive always returns 0 overall, but query errors still show?
    if not exited:
        sys.stdout.write("CTRL-D\n")
    sys.exit(0)

def main():
    argv = sys.argv
    args = argv[1:]
    nocolor = False
    no_errors = False
    config_warning = None
    i = 0
    # Flag processing loop
    while i < len(args):
        arg = args[i]
        low = arg.lower()
        # Help handling: only at i==0
        if is_help(arg):
            if i == 0:
                use_color = should_use_color(nocolor)
                print_help_long(use_color)
                sys.exit(0)
            else:
                break
        elif is_interactive(arg):
            # Interactive at any position triggers interactive (but after config consumption etc)
            # At this point, config_warning may have been set, etc.
            run_interactive(nocolor, no_errors, config_warning)
            return
        elif is_nocolor(arg):
            nocolor = True
            i += 1
            continue
        elif is_no_errors(arg):
            no_errors = True
            i += 1
            continue
        elif is_config(arg):
            if '=' in arg:
                prefix, suffix = arg.split('=',1)
                plow = prefix.lower()
                if suffix == "":
                    error_config_requires_path()
                elif is_help(suffix):
                    use_color = should_use_color(nocolor)
                    print_help_long(use_color)
                    sys.exit(0)
                elif is_nocolor(suffix):
                    nocolor = True
                    if i+1 >= len(args):
                        use_color = should_use_color(nocolor)
                        print_help_short(use_color)
                        sys.exit(0)
                    else:
                        i += 1
                        continue
                else:
                    # suffix ignored, consume next arg as config path
                    if i+1 >= len(args):
                        error_config_requires_path()
                    else:
                        config_path = args[i+1]
                        config_warning = handle_config_file(config_path)
                        i += 2
                        continue
            else:
                # spaced
                if i+1 >= len(args):
                    error_config_requires_path()
                else:
                    config_path = args[i+1]
                    config_warning = handle_config_file(config_path)
                    i += 2
                    continue
        else:
            break
    remaining = args[i:]
    if config_warning:
        sys.stderr.write(config_warning)
    if not remaining:
        use_color = should_use_color(nocolor)
        print_help_short(use_color)
        sys.exit(0)
    query_str = ' '.join(remaining)
    if query_str.strip() == "":
        use_color = should_use_color(nocolor)
        print_help_short(use_color)
        sys.exit(0)
    use_color = should_use_color(nocolor)
    out, err, code = execute_query(query_str, cwd=os.getcwd(), use_color=use_color)
    if out:
        sys.stdout.write(out)
    if err and not no_errors:
        sys.stderr.write(err)
    sys.exit(code)

if __name__ == "__main__":
    main()
PY
