        # kw can be multiword like "group by"
        # Use regex with word boundaries case-insensitive, but ensure not inside quotes
        pattern = re.compile(r'\b' + kw + r'\b', re.IGNORECASE)
        for m in pattern.finditer(s):
            # check if inside quotes
            # count quotes before m.start
            # simplistic: if odd number of single or double quotes before, inside
            prefix = s[:m.start()]
            # count unescaped quotes
            single = prefix.count("'") - prefix.count("\\'")
            double = prefix.count('"') - prefix.count('\\"')
            # if inside quotes, skip
            if single %2 ==1 or double %2 ==1:
                continue
            # also check if inside parentheses for functions? Not needed for keyword.
            return m.start(), m.end()
        return None

    # Determine positions
    pos_from = find_keyword(qs, r'from')
    pos_where = find_keyword(qs, r'where')
    pos_group = find_keyword(qs, r'group\s+by')
    pos_order = find_keyword(qs, r'order\s+by')
    pos_limit = find_keyword(qs, r'limit')
    pos_offset = find_keyword(qs, r'offset')
    pos_into = find_keyword(qs, r'into')

    # Sort positions
    positions = []
    for name, pos in [('from',pos_from),('where',pos_where),('group',pos_group),('order',pos_order),('limit',pos_limit),('offset',pos_offset),('into',pos_into)]:
        if pos:
            positions.append((pos[0], pos[1], name))
    positions.sort(key=lambda x: x[0])

    # Extract columns part: from start to first keyword or end
    if positions:
        first_pos = positions[0][0]
        cols_part = qs[:first_pos].strip()
        # Remove trailing comma?
    else:
        cols_part = qs.strip()

    # If cols_part empty? Then maybe no columns? In original, if no columns specified but just "invalid" ??? Actually "invalid" is considered column list with one column. So cols_part should be "invalid" or "name" etc.
    # For query like "name from ..." cols_part is "name"
    # Now extract details
    details = {}
    # Helper to extract segment between keywords
    # Build ordered list of keywords with their value segment
    # Create dict mapping name to segment string
    # For each position i, segment is from pos_end to next pos_start (or end)
    for idx, (start, end, name) in enumerate(positions):
        next_start = positions[idx+1][0] if idx+1 < len(positions) else len(qs)
        segment = qs[end:next_start].strip()
        details[name] = segment

    cols_str = cols_part
    from_str = details.get('from','')
    where_str = details.get('where','')
    group_str = details.get('group','')
    order_str = details.get('order','')
    limit_str = details.get('limit','')
    offset_str = details.get('offset','')
    into_str = details.get('into','')

    # Parse columns: split by comma not inside parentheses
    if cols_str.strip() == "":
        cols = []
    else:
        cols = [c.strip() for c in split_args(cols_str) if c.strip()!='']

    # Parse from: split by comma, each may have options after? For now take first token as path
    roots = []
    if from_str:
        # Split by comma
        root_parts = split_args(from_str)
        for rp in root_parts:
            rp = rp.strip()
            if not rp:
                continue
            # root may have options after path: e.g., "path maxdepth 1" or "path depth 2" or "path mindepth 2"
            # Extract path as first quoted or unquoted token, remainder are options
            # Use shlex split?
            # We'll handle simple: split but keep quoted path together
            # Use regex to extract path and options
            # Path may be quoted with ' or " or ` 
            m = re.match(r'''\s*(?P<path>'[^']*'|"[^"]*"|`[^`]*`|\S+)(?P<rest>.*)''', rp, re.DOTALL)
            if m:
                path_token = m.group('path').strip()
                rest = m.group('rest').strip()
                # Strip quotes from path_token
                if (path_token.startswith("'") and path_token.endswith("'")) or (path_token.startswith('"') and path_token.endswith('"')) or (path_token.startswith("`") and path_token.endswith("`")):
                    path_token = path_token[1:-1]
                # Also handle escaped single quotes? Not needed
                roots.append((path_token, rest))
            else:
                roots.append((rp, ""))

    # For roots without from clause, default to current dir (cwd)
    if not roots:
        roots = [('.', '')]

    return {
        'columns': cols,
        'roots': roots,
        'where': where_str,
        'group_by': group_str,
        'order_by': order_str,
        'limit': limit_str,
        'offset': offset_str,
        'into': into_str,
        'raw_from': from_str,
    }

def parse_size_filter(s):
    # Parse size values with units like 5m, 5mb, 1k, 1kb, etc for where comparisons
    # Return bytes as int
    s = s.strip().lower()
    # Remove quotes
    if (s.startswith("'") and s.endswith("'")) or (s.startswith('"') and s.endswith('"')):
        s = s[1:-1]
    # Match number + unit
    m = re.match(r'^(\d+(?:\.\d+)?)\s*([kmgt]?i?b?)$', s)
    if m:
        num = float(m.group(1))
        unit = m.group(2)
        mult = 1
        if unit in ('t','tib'): mult = 1024**4
        elif unit in ('tb',): mult = 1000**4
        elif unit in ('g','gib'): mult = 1024**3
        elif unit in ('gb',): mult = 1000**3
        elif unit in ('m','mib'): mult = 1024**2
        elif unit in ('mb',): mult = 1000**2
        elif unit in ('k','kib'): mult = 1024
        elif unit in ('kb',): mult = 1000
        elif unit in ('b',''): mult = 1
        return int(num * mult)
    # Try int
    try:
        return int(s)
    except:
        try:
            return int(float(s))
        except:
            return None

def evaluate_where(row_expr, path, st, rel, root, use_color):
    # Evaluate where expression - very simplified
    # Supports: col operator value, col between val and val, col in (...), col like pattern, col regexp pattern, exists subquery, etc.
    # We'll handle basic cases tested: size comparisons, name globs, like, regexp, between, in list, in subquery, exists
    where = row_expr.strip()
    if not where:
        return True
    # Handle logical and/or: split by ' and ' and ' or ' case-insensitive, but respecting parentheses
    # We'll handle by evaluating with recursion: find top-level or then and
    # Check for parentheses enclosing whole expression?
    # For simplicity, handle and/or by splitting outside parentheses
    # We'll look for " or " outside parens and quotes
    def split_logical(s, op):
        # op is ' or ' or ' and '
        depth = 0
        in_single = False
        in_double = False
        op_len = len(op)
        for i in range(len(s)):
            ch = s[i]
            if ch == "'" and not in_double:
                in_single = not in_single
            elif ch == '"' and not in_single:
                in_double = not in_double
            elif not in_single and not in_double:
                if ch == '(':
                    depth+=1
                elif ch == ')':
                    depth-=1
                elif depth==0 and s[i:i+op_len].lower() == op:
                    # check boundaries?
                    return s[:i].strip(), s[i+op_len:].strip()
        return None

    # Try or first (lower precedence)
    res = split_logical(where, ' or ')
    if res:
        left, right = res
        return evaluate_where(left, path, st, rel, root, use_color) or evaluate_where(right, path, st, rel, root, use_color)
    res = split_logical(where, ' and ')
    if res:
        left, right = res
        return evaluate_where(left, path, st, rel, root, use_color) and evaluate_where(right, path, st, rel, root, use_color)

    # Remove outer parentheses
    if where.startswith('(') and where.endswith(')'):
        # check balanced
        depth=0
        in_s=False
        in_d=False
        balanced=True
        for i,ch in enumerate(where):
            if ch=="'" and not in_d:
                in_s=not in_s
            elif ch=='"' and not in_s:
                in_d=not in_d
            elif not in_s and not in_d:
                if ch=='(':
                    depth+=1
                elif ch==')':
                    depth-=1
                    if depth==0 and i != len(where)-1:
                        balanced=False
                        break
        if balanced and depth==0:
            return evaluate_where(where[1:-1].strip(), path, st, rel, root, use_color)

    # Now handle simple expression: column operator value
    # Handle between
    m_between = re.match(r'''(?P<col>\S+)\s+between\s+(?P<low>\S+)\s+and\s+(?P<high>\S+)''', where, re.IGNORECASE)
    if m_between:
        col = m_between.group('col')
        low = m_between.group('low')
        high = m_between.group('high')
        val = get_column_value(path, st, rel, root, col)
        # Determine if numeric comparison (size) or string
        # Try size parse
        try:
            v = int(val)
            l = parse_size_filter(low)
            h = parse_size_filter(high)
            if l is None or h is None:
                return False
            return l <= v <= h
        except:
            # string compare
            return low <= val <= high

    # Handle in (...) with subquery or list
    m_in = re.match(r'''(?P<col>\S+)\s+in\s*(?P<vals>\(.*\))''', where, re.IGNORECASE|re.DOTALL)
    if m_in:
        col = m_in.group('col')
        vals_str = m_in.group('vals').strip()
        # Remove outer parentheses
        inner = vals_str[1:-1].strip()
        # Check if subquery: starts with select or looks like "select ..."
        if inner.lower().startswith('select '):
            # Subquery: need to execute subquery and get list of values for column?
            # But our where col is size etc, subquery is like "select size from /tmp/op_test where name = 'a.txt'"
            # We need to run subquery to get set
            # For simplicity, we will run execute_query on inner and collect first column values
            # But execute_query expects full query string like "size from /tmp/op_test where ..."
            # The inner already is "select size from ..."
            sub_out, _, _ = execute_query(inner, cwd=os.getcwd(), use_color=False)
            # sub_out lines are values
            sub_vals = [line.strip() for line in sub_out.splitlines() if line.strip()!=""]
            val = get_column_value(path, st, rel, root, col)
            return val in sub_vals
        else:
            # List of values comma separated, may have quotes
            list_vals = [v.strip().strip("'\"") for v in split_args(inner)]
            val = get_column_value(path, st, rel, root, col)
            # For size, need to compare numeric? List vals may be "10" etc.
            return val in list_vals

    # Handle not in? Not needed

    # Handle exists (...) 
    m_exists = re.match(r'''exists\s*\(.*\)''', where, re.IGNORECASE|re.DOTALL)
    if m_exists:
        # Extract inner query
        # where like "exists (select * from /tmp/op_test where name = 'a.txt')"
        # For exists, return true if subquery returns any rows
        # Also handle "not exists"
        # Check for not
        if where.lower().startswith('not '):
            where = where[4:].strip()
            m_exists = re.match(r'''exists\s*\((.*)\)''', where, re.IGNORECASE|re.DOTALL)
            if m_exists:
                inner = m_exists.group(1).strip()
                sub_out, _, _ = execute_query(inner, cwd=os.getcwd(), use_color=False)
                return len([l for l in sub_out.splitlines() if l.strip()!=""]) == 0
        else:
            m = re.match(r'''exists\s*\((.*)\)''', where, re.IGNORECASE|re.DOTALL)
            if m:
                inner = m.group(1).strip()
                sub_out, _, _ = execute_query(inner, cwd=os.getcwd(), use_color=False)
                return len([l for l in sub_out.splitlines() if l.strip()!=""]) > 0

    # Handle like / notlike
    m_like = re.match(r'''(?P<col>\S+)\s+(?P<op>like|notlike)\s+(?P<pat>\S+)''', where, re.IGNORECASE)
    if m_like:
        col = m_like.group('col')
        op = m_like.group('op').lower()
        pat = m_like.group('pat').strip().strip("'\"")
        val = get_column_value(path, st, rel, root, col)
        # Convert SQL like pattern to fnmatch: % -> *, _ -> ?
        # Need to handle % and _ wildcards
        # Also original fselect uses glob patterns for =? For like, % and _.
        regex_pat = re.escape(pat)
        regex_pat = regex_pat.replace(r'\%', '.*').replace(r'\_', '.')
        # But pat may contain * and ? already? For like, only % and _.
        # Use full match
        matched = re.match(r'^' + regex_pat + r'$', val, re.DOTALL) is not None
        return matched if op=='like' else not matched

    # Handle regexp / rx
    m_regex = re.match(r'''(?P<col>\S+)\s+(?P<op>regexp|rx|~=|=~)\s+(?P<pat>\S+)''', where, re.IGNORECASE)
    if m_regex:
        col = m_regex.group('col')
        pat = m_regex.group('pat').strip().strip("'\"")
        val = get_column_value(path, st, rel, root, col)
        try:
            matched = re.search(pat, val) is not None
        except:
            matched = False
        return matched
    m_notregex = re.match(r'''(?P<col>\S+)\s+(?P<op>notrx|!~=|!=~)\s+(?P<pat>\S+)''', where, re.IGNORECASE)
    if m_notregex:
        col = m_notregex.group('col')
        pat = m_notregex.group('pat').strip().strip("'\"")
        val = get_column_value(path, st, rel, root, col)
        try:
            matched = re.search(pat, val) is not None
        except:
            matched = False
        return not matched

    # Handle generic operator: col op value
    # Operators: = == eq === eeq != <> ne !== ene < lt <= lte le > gt >= gte ge
    # Need to parse col, op, value
    # Use regex: col whitespace op whitespace value
    # Value may be quoted string or number or glob
    # We'll try to match
    m_op = re.match(r'''(?P<col>\S+?)\s*(?P<op>===|!==|==|!=|<>|<=|>=|=~|~=|!~=|!=~|!~|eq|eeq|ne|ene|lt|lte|le|gt|gte|ge|=|<|>)\s*(?P<val>.+)''', where, re.IGNORECASE)
    if m_op:
        col = m_op.group('col').strip()
        op = m_op.group('op').strip().lower()
        val_raw = m_op.group('val').strip()
        # Remove surrounding quotes from val_raw if quoted
        val = val_raw.strip()
        if (val.startswith("'") and val.endswith("'")) or (val.startswith('"') and val.endswith('"')) or (val.startswith("`") and val.endswith("`")):
            val_inner = val[1:-1]
        else:
            val_inner = val
        col_val = get_column_value(path, st, rel, root, col)
        # For size comparisons, need to handle numeric with units
        # If col is size or similar numeric, parse both as ints after size conversion
        is_numeric_col = col.lower() in ('size','fsize','hsize','width','height','duration','uid','gid','inode','blocks','hardlinks','line_count','atime','mtime','ctime')
        if is_numeric_col:
            # Try to parse col_val and val_inner as numbers with units
            try:
                # col_val is already numeric string like "6"
                cv = int(col_val) if col_val != "" else 0
                # val_inner may be like "1k", "5m", "10", "5mib"
                # Use parse_size_filter for val_inner
                pv = parse_size_filter(val_inner)
                if pv is None:
                    # try float
                    pv = int(float(val_inner))
                # Now compare
                if op in ('=','==','eq', '===','eeq'):
                    # For size, strict equality same as normal
                    return cv == pv
                elif op in ('!=','<>','ne','!==','ene'):
                    return cv != pv
                elif op in ('<','lt'):
                    return cv < pv
                elif op in ('<=','lte','le'):
                    return cv <= pv
                elif op in ('>','gt'):
                    return cv > pv
                elif op in ('>=','gte','ge'):
                    return cv >= pv
                else:
                    return False
            except:
                # fallback to string
                pass
        # Non-numeric or fallback: handle string equality with glob for = ?
        # For = operator, original fselect treats value as glob pattern? Test: name = '*.txt' matched glob. For ==, same? For === strict? Let's check.
        # From help: = used to check equality, but with glob? In earlier tests: name = '*.txt' matched, name = 'a.txt' matched exact. So = does glob matching.
        # We saw: name = '*.txt' matched a.txt, name = 'a.txt' matched. So need to handle glob for = / == vs strict.
        # For === (eeq) strict equality without regex characters
        # For generic, we will treat:
        #  '=' , '==', 'eq' => glob match using fnmatch if pattern contains * or ? or [ else exact
        #  '===' , 'eeq' => exact string equality
        #  '!=' , '<>', 'ne' => glob not match
        #  '!==' , 'ene' => strict not equal
        if op in ('=','==','eq'):
            # glob match
            # If val_inner contains * or ? or [ then fnmatch, else exact
            if '*' in val_inner or '?' in val_inner or '[' in val_inner:
                return fnmatch.fnmatch(col_val, val_inner)
            else:
                return col_val == val_inner
        elif op in ('===','eeq'):
            return col_val == val_inner
        elif op in ('!=','<>','ne'):
            if '*' in val_inner or '?' in val_inner or '[' in val_inner:
                return not fnmatch.fnmatch(col_val, val_inner)
            else:
                return col_val != val_inner
        elif op in ('!==','ene'):
            return col_val != val_inner
        elif op in ('<','lt'):
            return col_val < val_inner
        elif op in ('<=','lte','le'):
            return col_val <= val_inner
        elif op in ('>','gt'):
            return col_val > val_inner
        elif op in ('>=','gte','ge'):
            return col_val >= val_inner
        elif op in ('=~','~=','regexp','rx'):
            try:
                return re.search(val_inner, col_val) is not None
            except:
                return False
        elif op in ('!~=','!=~','notrx'):
            try:
                return re.search(val_inner, col_val) is None
            except:
                return False
        else:
            return False

    # Handle boolean column short syntax: e.g., "where is_hidden = true" vs "where is_hidden" ?
    # In docs: where section can contain short syntax conditions for boolean columns (like is_audio or other_write)
    # So if where is just a column name like "is_hidden" or "is_audio", it means check true?
    # Test: where is_hidden = true gave results, but what about "where is_hidden" ?
    # Let's test: is_hidden alone?
    # For simplicity, if where is single word that is a boolean column, treat as true check
    low_where = where.lower()
    if low_where in ('is_hidden','is_dir','is_file','is_symlink','is_image','is_audio','is_video','is_archive','is_book','is_doc','is_font','is_source','is_hidden'):
        val = get_column_value(path, st, rel, root, where)
        return val == "true"
    if low_where.startswith('is_') or low_where in ('is_hidden',):
        try:
            val = get_column_value(path, st, rel, root, where)
            return val == "true"
        except:
            pass

    # Unknown expression: try to treat as true? Or false for filtering? In earlier test "where invalid = 1" gave empty result (false), not error. So unknown column compared to value returns false.
    # For expression like "where invalid" ? Not needed.
    # If parsing fails, return false? But also need to handle "where invalid" single word invalid should maybe be true? Not needed.
    # For now, if cannot parse, return False? But then "where invalid = 1" gave no results (since no row matches), which matches False.
    # For "where" with empty? Already handled.
    # If where is something like "size > 0" but parsing succeeded above, we would have returned.
    # If still not matched, we can try to evaluate as string truthiness: if col value exists? 
    # We'll return False for safety.
    # But also need to handle case where where is just "name = 'a.txt' and ..." already handled via logical split.
    # For fallback, try to evaluate as python? Not.
    return False

def collect_files(root_path_str, rest_options, cwd):
