    if order == 'dfs':
        stack = [(root_abs, 0)]
        # For DFS, we will traverse depth-first, but we need to respect mindepth/maxdepth filtering after.
        # Instead we can do recursive DFS via stack LIFO
        visited = set()
        while stack:
            cur, depth = stack.pop()
            # cur is directory at depth
